(()=>{const btn=document.querySelector('.nav-toggle'),nav=document.querySelector('.site-nav');if(btn&&nav){btn.addEventListener('click',()=>{const open=nav.classList.toggle('open');btn.setAttribute('aria-expanded',String(open));btn.setAttribute('aria-label',open?'Cerrar menú':'Abrir menú')});nav.addEventListener('click',e=>{if(e.target.closest('a')){nav.classList.remove('open');btn.setAttribute('aria-expanded','false')}})}document.querySelectorAll('a[target="_blank"]').forEach(a=>{if(!a.rel)a.rel='noopener noreferrer'})})();
